from PIL import Image

img = Image.open('/app/output/final_poster.png')

# Create a scaled-down version for quick visual check
thumb = img.resize((700, 993), Image.LANCZOS)
thumb.save('/app/output/poster_thumb.png')

# Count pixels by color family across the full poster to verify palette
from collections import Counter
colors = Counter()
for y in range(0, 4967, 20):
    for x in range(0, 3508, 20):
        p = img.getpixel((x, y))
        r, g, b = p
        if r < 30 and g < 30 and b < 50:
            colors['dark_bg'] += 1
        elif g > 150 and b > 100 and r < 50:
            colors['teal'] += 1
        elif b > 150 and r < 80:
            colors['blue'] += 1
        elif r > 200 and g < 100:
            colors['red'] += 1
        elif r > 200 and g > 200 and b > 200:
            colors['white'] += 1
        elif r > 200 and g > 150 and b < 50:
            colors['amber'] += 1
        elif g > 200 and r < 50 and b < 100:
            colors['green'] += 1
        else:
            colors['other'] += 1

total = sum(colors.values())
for k, v in sorted(colors.items(), key=lambda x: -x[1]):
    pct = v / total * 100
    print(f'{k:10s}: {v:5d} ({pct:5.1f}%)')
"

